set -Eeuo pipefail
export PYTHONDONTWRITEBYTECODE=1
python3 - <<'PY'
from pathlib import Path
import os,json,subprocess
print("CHECK_USER",os.getuid(),flush=True)
print("CHECK_HOST",os.uname().nodename,flush=True)
found=[]
inaccessible=0
for p in Path("/proc").iterdir():
 if not p.name.isdigit(): continue
 try:
  comm=(p/"comm").read_text().strip().lower()
  if comm not in {"python","python3","codex","node","nodejs","pm2","pm2 daemon"}: continue
  args=(p/"cmdline").read_bytes().replace(b"\x00",b" ").decode("utf-8","replace").lower()
 except (OSError,PermissionError):
  inaccessible+=1
  continue
 if any(k in args for k in ("ops.coordinator_ai","ops/coordinator_ai.py","coordinator_phase_continuation.py","coordinator-owner-order")):
  found.append((int(p.name),comm))
print("LIVE_COORDINATOR_PROCESS_MATCHES",len(found),flush=True)
for pid,comm in found: print("MATCH_PROCESS",pid,comm,flush=True)
print("UNREADABLE_SCANNED_PROCESSES",inaccessible,flush=True)
try:
 x=subprocess.run(["systemctl","list-units","--all","--type=service","--no-legend","--no-pager"],capture_output=True,text=True,timeout=12)
 if x.returncode:
  print("SYSTEMD_OBSERVATION_UNAVAILABLE",x.returncode,flush=True)
 else:
  chosen=[ln.split()[0] for ln in x.stdout.splitlines() if "coordinator" in ln.lower() or "project-leader" in ln.lower()]
  print("MATCHING_SERVICE_UNITS",chosen,flush=True)
except (OSError,subprocess.TimeoutExpired) as exc: print("SYSTEMD_OBSERVATION_UNAVAILABLE",type(exc).__name__,flush=True)
for path in (Path("/home/ubuntu/.pm2/dump.pm2"),Path("/home/ubuntu/.pm2/pm2.pid")):
 if path.name.endswith(".pid"):
  print("UBUNTU_PM2_PID_FILE_PRESENT",path.exists(),flush=True)
  continue
 if path.is_file():
  try:
   data=json.loads(path.read_text())
   matches=[str(item.get("name","")) for item in data if "coordinator" in str(item.get("name","")).lower() or "project-leader" in str(item.get("name","")).lower()]
   print("UBUNTU_PM2_DUMP_COORDINATOR_NAMES",matches,flush=True)
  except (OSError,ValueError,TypeError): print("UBUNTU_PM2_DUMP_UNREADABLE",flush=True)
 else: print("UBUNTU_PM2_DUMP_MISSING",flush=True)
print("LIVE_SCAN_COMPLETE",flush=True)
PY
